"""
Register Prescriber editor's data model
"""
from interops.libraries.mosaiq.interactions.objects.mosaiq_staff_register_prescriber_editor_objects import RegisterPrescriberEditorObjects
from interops.libraries.mosaiq.interactions.objects.mosaiq_staff_register_prescriber_objects import RegisterPrescriberObjects
from interops.libraries.common.state import State
from interops.libraries.squish_actions import CommonActions

class RegisterPrescriberEditor():
    def __init__(self) -> None:
        #Panes
        self.departments = State(RegisterPrescriberEditorObjects.departments_Name_Pane, "")
        self.department_locatioon = State(RegisterPrescriberEditorObjects.department_Location_Pane, "")
        self.spi_id = State(RegisterPrescriberEditorObjects.sPID_Pane, "")
        self.do_not_process = State(RegisterPrescriberEditorObjects.do_Not_Process_CheckBox)
        self.service_level = {
            "New Rx": State(RegisterPrescriberEditorObjects.new_Rx_CheckBox),
            "Refill": State(RegisterPrescriberEditorObjects.refill_CheckBox),
            "Change": State(RegisterPrescriberEditorObjects.change_CheckBox),
            "Cancel": State(RegisterPrescriberEditorObjects.cancel_CheckBox),
            "RxFill": State(RegisterPrescriberEditorObjects.rxFill_CheckBox),
            "Inactive": State(RegisterPrescriberEditorObjects.inactive_CheckBox)
        }
    def click_ok(self):
        CommonActions.left_click_object(RegisterPrescriberEditorObjects.oK_Button)

    def click_cancel(self):
        CommonActions.left_click_object(RegisterPrescriberEditorObjects.cancel_Button)

class RegisterPrescriber():
    """Class of Register Prescriber, used to model the window's elements and operations"""
    def __init__(self) -> None:
        #CommonActions.wait_for_object_exists(RegisterPrescriberObjects.register_Prescriber_Window)
        pass

    class ServiceLevel:
        """Inner class to model Service Level"""
        def __init__(self):
            self.data = {
            "New Rx": False,
            "Refill": False,
            "Change": False,
            "Cancel": False,
            "RxFill": False,
            "Inactive": False
        }

    def click_button(self, btn: str):
        '''
        Click a button given by its name.
        '''
        _button = {
            "Close": RegisterPrescriberObjects.close_Button,
            "Change":RegisterPrescriberObjects.change_Button,
            "Process":RegisterPrescriberObjects.process_Button,
            "Register":RegisterPrescriberObjects.register_Button,
            "Access Control":RegisterPrescriberObjects.access_Control_Button
           }

        if btn in _button:
            CommonActions.left_click_object(_button[btn])

    def get_service_level(self):
        editor = RegisterPrescriberEditor()
        service_level = self.ServiceLevel()
        for key in editor.service_level.keys():
            service_level.data[key] = editor.service_level[key].value
        return service_level

    def set_servcer_level(self, value: ServiceLevel):
        editor = RegisterPrescriberEditor()
        for key in editor.service_level.keys():
            if key in value.data:
                editor.service_level[key].value = value.data[key]
